import type { Skill } from '../types';

/**
 * Factory function for creating mock skill data
 */
export function createMockSkill(overrides?: Partial<Skill>): Skill {
  return {
    id: 'test-skill',
    name: 'Test Skill',
    description: 'A test skill for testing purposes',
    category: 'testing',
    risk: 'safe',
    source: 'test',
    date_added: '2024-01-01',
    path: 'skills/test/SKILL.md',
    ...overrides,
  };
}

/**
 * Factory function for creating an array of mock skills
 */
export function createMockSkills(count: number): Skill[] {
  return Array.from({ length: count }, (_, i) =>
    createMockSkill({
      id: `skill-${i}`,
      name: `Test Skill ${i}`,
    })
  );
}

/**
 * Factory for creating skills with different categories
 */
export function createMockSkillsByCategory(categories: string[]): Skill[] {
  return categories.flatMap((category) =>
    Array.from({ length: 3 }, (_, i) =>
      createMockSkill({
        id: `${category}-skill-${i}`,
        name: `${category} Skill ${i}`,
        category,
      })
    )
  );
}

import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';
import { renderHook, act, waitFor } from '@testing-library/react';
import { useSkillShortlist } from '../useSkillShortlist';

const STORAGE_KEY = 'aas_skill_shortlist';

describe('useSkillShortlist', () => {
  beforeEach(() => {
    localStorage.clear();
    vi.clearAllMocks();
  });

  afterEach(() => {
    vi.restoreAllMocks();
  });

  describe('Initialization', () => {
    it('starts empty when nothing is stored', () => {
      const { result } = renderHook(() => useSkillShortlist());
      expect(result.current.ids).toEqual([]);
    });

    it('reads an existing shortlist from localStorage', () => {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(['skill-1', 'skill-2']));
      const { result } = renderHook(() => useSkillShortlist());
      expect(result.current.ids).toEqual(['skill-1', 'skill-2']);
    });

    it('falls back to an empty list for corrupted storage', () => {
      localStorage.setItem(STORAGE_KEY, 'not-json{');
      const { result } = renderHook(() => useSkillShortlist());
      expect(result.current.ids).toEqual([]);
    });

    it('drops non-string entries from stored JSON', () => {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(['skill-1', 42, null, 'skill-2']));
      const { result } = renderHook(() => useSkillShortlist());
      expect(result.current.ids).toEqual(['skill-1', 'skill-2']);
    });

    it('stays usable when the browser rejects storage reads', () => {
      vi.spyOn(Storage.prototype, 'getItem').mockImplementation(() => {
        throw new DOMException('Storage access denied', 'SecurityError');
      });

      expect(() => renderHook(() => useSkillShortlist())).not.toThrow();
    });
  });

  describe('toggle', () => {
    it('adds a skill that was not selected', () => {
      const { result } = renderHook(() => useSkillShortlist());
      act(() => result.current.toggle('react'));
      expect(result.current.ids).toEqual(['react']);
    });

    it('removes a skill that was already selected', () => {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(['react', 'sql']));
      const { result } = renderHook(() => useSkillShortlist());
      act(() => result.current.toggle('react'));
      expect(result.current.ids).toEqual(['sql']);
    });

    it('persists additions to localStorage', () => {
      const { result } = renderHook(() => useSkillShortlist());
      act(() => result.current.toggle('react'));
      expect(JSON.parse(localStorage.getItem(STORAGE_KEY) || '[]')).toEqual(['react']);
    });

    it('stays referentially stable across renders (memo-friendly)', () => {
      const { result, rerender } = renderHook(() => useSkillShortlist());
      const toggle = result.current.toggle;
      rerender();
      expect(result.current.toggle).toBe(toggle);
    });
  });

  describe('clear', () => {
    it('empties the selected ids and storage', () => {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(['a', 'b']));
      const { result } = renderHook(() => useSkillShortlist());
      act(() => result.current.clear());
      expect(result.current.ids).toEqual([]);
      expect(JSON.parse(localStorage.getItem(STORAGE_KEY) || '[]')).toEqual([]);
    });
  });

  describe('Cross-tab / cross-hook sync', () => {
    it('syncs when another tab writes via the storage event', async () => {
      const { result } = renderHook(() => useSkillShortlist());
      act(() => {
        localStorage.setItem(STORAGE_KEY, JSON.stringify(['external-skill']));
        window.dispatchEvent(new Event('storage'));
      });
      await waitFor(() => expect(result.current.ids).toEqual(['external-skill']));
    });

    it('syncs a second hook when the first toggles a skill', async () => {
      const first = renderHook(() => useSkillShortlist());
      const second = renderHook(() => useSkillShortlist());

      act(() => first.result.current.toggle('shared-skill'));

      await waitFor(() => expect(second.result.current.ids).toEqual(['shared-skill']));
    });
  });
});

import { describe, it, expect, vi, beforeEach } from 'vitest';
import { renderHook, act, waitFor } from '@testing-library/react';
import { useSkillStars } from '../useSkillStars';

const STORAGE_KEY = 'saved_skills';
const LEGACY_STORAGE_KEY = 'user_stars';

describe('useSkillStars', () => {
  beforeEach(() => {
    localStorage.clear();
    vi.clearAllMocks();
  });

  describe('Initialization', () => {
    it('should initialize as unsaved when no skillId is provided', () => {
      const { result } = renderHook(() => useSkillStars(undefined));

      expect(result.current.hasSaved).toBe(false);
      expect(result.current.isSaving).toBe(false);
    });

    it('should initialize as unsaved for a new skill', () => {
      const { result } = renderHook(() => useSkillStars('new-skill'));

      expect(result.current.hasSaved).toBe(false);
    });

    it('should read saved state from the new storage key', async () => {
      localStorage.setItem(STORAGE_KEY, JSON.stringify({ 'test-skill': true }));

      const { result } = renderHook(() => useSkillStars('test-skill'));

      await waitFor(() => {
        expect(result.current.hasSaved).toBe(true);
      });
    });

    it('should read saved state from the legacy storage key', async () => {
      localStorage.setItem(LEGACY_STORAGE_KEY, JSON.stringify({ 'test-skill': true }));

      const { result } = renderHook(() => useSkillStars('test-skill'));

      await waitFor(() => {
        expect(result.current.hasSaved).toBe(true);
      });
    });

    it('should handle corrupted localStorage gracefully', () => {
      const consoleSpy = vi.spyOn(console, 'warn').mockImplementation(() => {});
      localStorage.setItem(STORAGE_KEY, 'invalid-json');

      const { result } = renderHook(() => useSkillStars('test-skill'));

      expect(result.current.hasSaved).toBe(false);
      expect(consoleSpy).toHaveBeenCalledWith(
        `Failed to parse ${STORAGE_KEY} from localStorage:`,
        expect.any(Error)
      );

      consoleSpy.mockRestore();
    });
  });

  describe('handleSaveClick', () => {
    it('should not allow saving without skillId', async () => {
      const { result } = renderHook(() => useSkillStars(undefined));

      await act(async () => {
        await result.current.handleSaveClick();
      });

      expect(result.current.hasSaved).toBe(false);
      expect(localStorage.setItem).not.toHaveBeenCalled();
    });

    it('should not allow double-saving the same skill', async () => {
      localStorage.setItem(STORAGE_KEY, JSON.stringify({ 'skill-1': true }));

      const { result } = renderHook(() => useSkillStars('skill-1'));

      await act(async () => {
        await result.current.handleSaveClick();
      });

      expect(result.current.hasSaved).toBe(true);
    });

    it('should optimistically mark the skill as saved', async () => {
      const { result } = renderHook(() => useSkillStars('optimistic-skill'));

      expect(result.current.hasSaved).toBe(false);

      await act(async () => {
        await result.current.handleSaveClick();
      });

      await waitFor(() => {
        expect(result.current.hasSaved).toBe(true);
      });
    });

    it('should persist saved status to localStorage', async () => {
      const { result } = renderHook(() => useSkillStars('persist-skill'));

      await act(async () => {
        await result.current.handleSaveClick();
      });

      expect(localStorage.setItem).toHaveBeenCalledWith(
        STORAGE_KEY,
        JSON.stringify({ 'persist-skill': true })
      );
    });

    it('should expose a settled saving state after completion', async () => {
      const { result } = renderHook(() => useSkillStars('loading-skill'));

      await waitFor(() => {
        expect(result.current.isSaving).toBe(false);
      });

      await act(async () => {
        await result.current.handleSaveClick();
      });

      expect(result.current.isSaving).toBe(false);
    });
  });

  describe('LocalStorage error handling', () => {
    it('should handle setItem errors gracefully', async () => {
      const consoleSpy = vi.spyOn(console, 'warn').mockImplementation(() => {});

      localStorage.setItem = vi.fn(() => {
        throw new Error('Storage quota exceeded');
      });

      const { result } = renderHook(() => useSkillStars('error-skill'));

      await act(async () => {
        await result.current.handleSaveClick();
      });

      expect(result.current.hasSaved).toBe(true);
      expect(consoleSpy).toHaveBeenCalledWith(
        `Failed to save ${STORAGE_KEY} to localStorage:`,
        expect.any(Error)
      );

      consoleSpy.mockRestore();
    });
  });

  describe('Return values', () => {
    it('should return all expected properties', () => {
      const { result } = renderHook(() => useSkillStars('test'));

      expect(result.current).toHaveProperty('hasSaved');
      expect(result.current).toHaveProperty('handleSaveClick');
      expect(result.current).toHaveProperty('isSaving');
    });

    it('should expose handleSaveClick as function', () => {
      const { result } = renderHook(() => useSkillStars('test'));

      expect(typeof result.current.handleSaveClick).toBe('function');
    });
  });
});

import { describe, it, expect, vi, beforeEach } from 'vitest';
