  color: var(--text-muted);
  font-size: 0.78rem;
}

.workbench-review-empty h2 {
  margin: 8px 0;
  font-size: 1.7rem;
}

.workbench-review {
  border: 1px solid var(--stroke-subtle);
  border-radius: var(--radius-sm);
  background: var(--surface-card);
}

.workbench-review > header,
.workbench-review > section,
.workbench-review > div {
  padding: 20px;
  border-bottom: 1px solid var(--stroke-subtle);
}

.workbench-review > :last-child {
  border-bottom: 0;
}

.workbench-review__heading,
.workbench-review__section-heading {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 18px;
}

.workbench-review__heading p {
  margin: 0 0 4px;
  color: var(--accent-solid);
  font-family: var(--font-mono);
  font-size: 0.66rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.workbench-review__heading h2,
.workbench-review h3 {
  margin: 0;
}

.workbench-review__heading h2 {
  font-size: 1.35rem;
}

.workbench-review h3 {
  font-size: 0.9rem;
}

.workbench-review__heading > span,
.workbench-review__section-heading > span,
.workbench-review h3 > span {
  color: var(--text-muted);
  font-family: var(--font-mono);
  font-size: 0.68rem;
  font-weight: 400;
}

.workbench-review__note,
.workbench-review__empty {
  margin: 7px 0 0;
  color: var(--text-muted);
  font-size: 0.72rem;
}

.workbench-review__columns {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 32px;
}

.workbench-review__columns > section + section {
