  border-left: 1px solid var(--stroke-subtle);
}

.workbench-review__facts {
  display: grid;
  gap: 0;
  margin: 12px 0 0;
  border-top: 1px solid var(--stroke-subtle);
}

.workbench-review__facts > div {
  display: grid;
  grid-template-columns: minmax(110px, 0.35fr) minmax(0, 1fr);
  gap: 20px;
  padding: 8px 0;
  border-bottom: 1px solid var(--stroke-subtle);
  font-size: 0.74rem;
}

.workbench-review__facts dt {
  color: var(--text-muted);
}

.workbench-review__facts dd {
  min-width: 0;
  margin: 0;
  overflow-wrap: anywhere;
  color: var(--text-primary);
}

.workbench-review code {
  font-family: var(--font-mono);
  font-size: 0.69rem;
}

.workbench-review__rows,
.workbench-review__code-list,
.workbench-review__operation-list,
.workbench-review__override-list {
  margin: 12px 0 0;
  padding: 0;
  list-style: none;
}

.workbench-review__rows li,
.workbench-review__code-list li {
  display: flex;
  justify-content: space-between;
  gap: 14px;
  padding: 8px 0;
  border-bottom: 1px solid var(--stroke-subtle);
  font-size: 0.75rem;
}

.workbench-review__rows li span {
  color: var(--text-muted);
  font-family: var(--font-mono);
}

.workbench-review__operation-list,
.workbench-review__override-list {
  display: grid;
  gap: 8px;
}

.workbench-review__operation-list > li,
.workbench-review__override-list > li {
