  border: 1px solid var(--stroke-subtle);
  border-radius: var(--radius-sm);
  background: var(--surface-canvas);
}

.workbench-review__operation-list header,
.workbench-review__override-list header {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 12px;
  align-items: baseline;
  font-size: 0.75rem;
}

.workbench-review__operation-list header span {
  margin-left: auto;
  color: #b45309;
  font-size: 0.65rem;
  font-weight: 650;
  text-transform: uppercase;
}

.workbench-review__operation-list .workbench-review__facts {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.workbench-review__operation-list .workbench-review__facts > div {
  display: block;
}

.workbench-review__operation-list .workbench-review__facts dd {
  margin-top: 4px;
}

.workbench-review__attention {
  background: color-mix(in srgb, #f59e0b 6%, var(--surface-card));
}

.workbench-review__override-list p {
  margin: 8px 0 0;
  color: var(--text-secondary);
  font-size: 0.72rem;
  overflow-wrap: anywhere;
}

.workbench-review__override-list p span {
  display: inline-block;
  min-width: 96px;
  color: var(--text-muted);
}

.plugins-page {
  padding: 0 48px 72px;
}

.plugins-hero {
  padding: 54px 0 30px;
  border-bottom: 1px solid var(--stroke-subtle);
}

.plugins-hero h1 {
