}

.plugin-decisions article:last-child {
  border-right: 0;
}

.plugin-decisions h3,
.plugin-decisions p {
  margin: 0;
}

.plugin-decisions h3 {
  font-size: 0.88rem;
}

.plugin-decisions p {
  margin-top: 8px;
  color: var(--text-secondary);
  font-size: 0.8rem;
  line-height: 1.5;
}

.plugin-catalog {
  padding-top: 28px;
}

.plugin-catalog > header {
