  align-items: end;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 28px;
}

.plugin-catalog > header h2,
.plugin-catalog > header p {
  margin: 0;
}

.plugin-catalog > header h2 {
  font-size: 1.35rem;
}

.plugin-catalog > header p {
